import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        long x = nextLong();
        long sign = x < 0 ? -1 : 1, reversed = 0;
        x = Math.abs(x);
        while (x != 0) { // append the lowest digit each step
            reversed = reversed * 10 + x % 10;
            x /= 10;
        }
        reversed *= sign;
        System.out.println(reversed >= Integer.MIN_VALUE && reversed <= Integer.MAX_VALUE ? reversed : 0);
    }
}

